from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query

NOW = datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)


def _task(id, title="task", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
          due_at=None, tags=None, created_at=None):
    return Task(
        id=id, title=title, status=status, priority=priority,
        due_at=due_at, tags=tags or [],
        created_at=created_at or datetime(2025, 1, id, tzinfo=timezone.utc),
    )


TASKS = [
    _task(1, "Alpha", priority=TaskPriority.HIGH, tags=[Tag("work")]),
    _task(2, "Beta", status=TaskStatus.DONE, tags=[Tag("personal")]),
    _task(3, "Gamma", due_at=datetime(2024, 1, 1, tzinfo=timezone.utc), tags=[Tag("work")]),
    _task(4, "Delta", priority=TaskPriority.LOW,
          due_at=datetime(2026, 1, 1, tzinfo=timezone.utc)),
    _task(5, "Epsilon", tags=[Tag("work"), Tag("urgent")]),
]


