    def test_by_tag(self):
        page = apply_query(TASKS, TaskQuery(tag="work"), NOW)
        assert page.total == 3
        assert all(any(t.name == "work" for t in item.tags) for item in page.items)

    def test_by_tag_case_insensitive(self):
        page = apply_query(TASKS, TaskQuery(tag="WORK"), NOW)
        assert page.total == 3


