        page = apply_query(TASKS, TaskQuery(search="alph"), NOW)
        assert page.total == 1
        assert page.items[0].title == "Alpha"

    def test_search_case_insensitive(self):
        page = apply_query(TASKS, TaskQuery(search="BETA"), NOW)
        assert page.total == 1

    def test_blank_search_ignored(self):
        page = apply_query(TASKS, TaskQuery(search="   "), NOW)
        assert page.total == 5


